// src/components/DeliveryTracking.tsx

import React, { useEffect, useState, useRef } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";
import {
  GoogleMap,
  Marker,
  DirectionsRenderer,
  useJsApiLoader
} from "@react-google-maps/api";

// Backend base URL
const API_BASE_URL = process.env.REACT_APP_API_URL || "http://localhost:5000";
// Your Google Maps API key
const GOOGLE_MAPS_API_KEY = process.env.REACT_APP_GOOGLE_MAPS_API_KEY || "";

const containerStyle = { width: "100%", height: "600px" };
// Fallback center while we load coordinates
const defaultCenter = { lat: 6.9271, lng: 79.8612 };

export default function DeliveryTracking() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const mapRef = useRef<google.maps.Map | null>(null);

  // State for coordinates and directions
  const [driverLocation, setDriverLocation] = useState<google.maps.LatLngLiteral | null>(null);
  const [destination, setDestination] = useState<google.maps.LatLngLiteral | null>(null);
  const [directions, setDirections] = useState<google.maps.DirectionsResult | null>(null);

  // Load the Google Maps JS API
  const { isLoaded } = useJsApiLoader({
    googleMapsApiKey: GOOGLE_MAPS_API_KEY,
    libraries: ["places"]
  });

  // 1️⃣ Fetch the delivery and driver, then geocode the driver's address
  useEffect(() => {
    if (!id) return;

    (async () => {
      try {
        // Get delivery data
        const { data: delivery } = await axios.get(`${API_BASE_URL}/api/delivery/${id}`);
        setDestination(delivery.location);

        // Get driver data
        const { data: driver } = await axios.get(
          `${API_BASE_URL}/api/drivers/${delivery.driverId}`
        );

        // Geocode the driver's address to lat/lng
        const { data: geo } = await axios.get(
          `https://maps.googleapis.com/maps/api/geocode/json`,
          {
            params: {
              address: driver.address,
              key: GOOGLE_MAPS_API_KEY
            }
          }
        );
        const loc = geo.results[0].geometry.location;
        setDriverLocation({ lat: loc.lat, lng: loc.lng });
      } catch (error) {
        console.error("Error fetching or geocoding data:", error);
      }
    })();
  }, [id]);

  // 2️⃣ Once both points are available and the API is loaded, request and render the route
  useEffect(() => {
    if (!isLoaded || !driverLocation || !destination) return;

    const service = new google.maps.DirectionsService();
    service.route(
      {
        origin: driverLocation,
        destination,
        travelMode: google.maps.TravelMode.DRIVING
      },
      (result, status) => {
        console.log("Directions status:", status);
        if (status === "OK" && result) {
          setDirections(result);
          // Fit the map bounds to the route
          mapRef.current?.fitBounds(result.routes[0].bounds);
        }
      }
    );
  }, [isLoaded, driverLocation, destination]);

  if (!isLoaded) return <div>Loading map…</div>;

  return (
    <div style={{ padding: 20 }}>
      {/* Back button */}
      <button
        onClick={() => navigate(-1)}
        style={{
          marginBottom: 10,
          padding: "8px 16px",
          background: "#6c757d",
          color: "#fff",
          border: "none",
          borderRadius: 4,
          cursor: "pointer"
        }}
      >
        ← Back
      </button>

      {/* Google Map */}
      <GoogleMap
        mapContainerStyle={containerStyle}
        center={driverLocation || destination || defaultCenter}
        zoom={12} // initial zoom; will auto-adjust when directions load
        onLoad={(map) => { mapRef.current = map; }}
      >
        {/* Driver marker */}
        {driverLocation && (
          <Marker position={driverLocation} label="🚚" />
        )}

        {/* Delivery marker */}
        {destination && (
          <Marker position={destination} label="📍" />
        )}

        {/* DirectionsRenderer draws the actual driving route */}
        {directions && (
          <DirectionsRenderer
            directions={directions}
            options={{
              suppressMarkers: true,  // keep our custom emoji markers
              polylineOptions: {
                strokeColor: "#1E90FF",
                strokeOpacity: 0.8,
                strokeWeight: 6
              }
            }}
          />
        )}
      </GoogleMap>
    </div>
  );
}
